svg.script:
    var r = document.getElementById('signature_svg'),
        p = document.getElementById('p'),
        signaturePath = '',
        isDown = false;

	top.getSignature = getSignature;
	top.clearSignature = clearSignature;

    function isTouchEvent(e) {
      return e.type.match(/^touch/);
    }

    function getCoords(e) {
      if (isTouchEvent(e)) {
        return e.targetTouches[0].clientX + ',' + e.targetTouches[0].clientY;
      }
      return e.clientX + ',' + e.clientY;
    }

    function down(e) {
      signaturePath += 'M' + getCoords(e) + ' ';
      p.setAttribute('d', signaturePath);
      isDown = true;

      if (isTouchEvent(e)) e.preventDefault();
    }

    function move(e) {
      if (isDown) {
        signaturePath += 'L' + getCoords(e) + ' ';
        p.setAttribute('d', signaturePath);
      }

      if (isTouchEvent(e)) e.preventDefault();
    }

    function up(e) {
      isDown = false; 

      if (isTouchEvent(e)) e.preventDefault();
    }

    r.addEventListener('mousedown', down, false);
    r.addEventListener('mousemove', move, false);
    r.addEventListener('mouseup', up, false);
    r.addEventListener('touchstart', down, false);
    r.addEventListener('touchmove', move, false);
    r.addEventListener('touchend', up, false);
    r.addEventListener('mouseout', up, false);
	//window.document.body.addEventListener('touchmove', function(event) { if (isDown) {event.preventDefault() }else{alert('2');} });

    function clearSignature() {
      signaturePath = '';
      p.setAttribute('d', '');
    }

    function getSignature() {
      return signaturePath;
    }
